"""
Optimized matrix square root solver.

Computes the principal matrix square root X such that X @ X = A,
where X is the unique matrix with eigenvalues having non-negative real parts.
"""

import logging
import numpy as np
import scipy.linalg
from typing import Any


class Solver:
    def solve(self, problem: dict, **kwargs) -> dict[str, dict[str, list[list[complex]]]]:
        """
        Solves the matrix square root problem using scipy.linalg.sqrtm.

        Computes the principal matrix square root X such that X @ X = A.

        :param problem: A dictionary representing the matrix square root problem.
            Expected keys: "matrix" - 2D array of complex numbers.
        :return: A dictionary with key "sqrtm" containing a dictionary with key:
                 "X": A list of lists representing the principal square root matrix X.
        """
        # Extract matrix from problem
        matrix_data = problem.get("matrix")

        if matrix_data is None:
            logging.error("Problem does not contain 'matrix'.")
            return {"sqrtm": {"X": []}}

        # Convert input to numpy array efficiently
        # Handle both list-of-lists and numpy array inputs
        if isinstance(matrix_data, np.ndarray):
            A = matrix_data.astype(complex)
        else:
            A = np.array(matrix_data, dtype=complex)

        n = A.shape[0]

        # Handle edge cases
        if n == 0:
            return {"sqrtm": {"X": []}}

        if n == 1:
            # For 1x1 matrix, compute sqrt directly
            val = A[0, 0]
            sqrt_val = self._complex_sqrt(val)
            return {"sqrtm": {"X": [[sqrt_val]]}}

        # Compute the principal matrix square root
        # Using optimized parameters:
        # - disp=False to suppress stdout warnings
        # - blocksize=128 for better cache utilization on larger matrices
        # - dissipation=1.0 for numerical stability
        try:
            X, _ = scipy.linalg.sqrtm(
                A,
                disp=False,
                blocksize=128,
                dissipation=1.0
            )
        except Exception as e:
            logging.error(f"scipy.linalg.sqrtm failed: {e}")
            return {"sqrtm": {"X": []}}

        # Convert to list for JSON serialization
        solution = {"sqrtm": {"X": X.tolist()}}
        return solution

    def _complex_sqrt(self, z: complex) -> complex:
        """
        Compute principal square root of a complex number.
        Returns the root with non-negative real part.
        """
        if z.imag == 0:
            if z.real >= 0:
                return complex(np.sqrt(z.real), 0)
            else:
                return complex(0, np.sqrt(-z.real))

        # General complex case using cmath
        import cmath
        sqrt = cmath.sqrt(z)
        # Ensure non-negative real part
        if sqrt.real < -1e-10:
            sqrt = -sqrt
        elif abs(sqrt.real) < 1e-10 and sqrt.imag < -1e-10:
            sqrt = -sqrt
        return sqrt

